iconFiles.search='search';
// Task and focus surfaces share the existing account state and action handlers.
let taskQuery='',taskSubjectFilter='',taskPriorityFilter='',taskSortOrder='date';
const taskPriorityNames={high:'Prioritaire',medium:'Normale',low:'Flexible'};
function taskMatchesView(t,view=taskView){
 const today=todayISO();
 return view==='today'?t.date===today:view==='upcoming'?!t.done&&t.date>today:view==='overdue'?!t.done&&t.date&&t.date<today:view==='open'?!t.done:view==='done'?t.done:true;
}
function taskWorkspaceRow(t){
 const overdue=!t.done&&t.date&&t.date<todayISO(),date=t.date===todayISO()?'Aujourd’hui':t.date?formatShort(t.date):'Sans date';
 return `<article class="task-work-row ${t.done?'is-done':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="${t.done?'Rouvrir':'Terminer'} : ${esc(t.title)}"><div class="task-work-copy"><button type="button" data-task-edit="${esc(t.id)}">${esc(t.title)}</button><div>${t.subject?`<span class="task-subject">${esc(t.subject)}</span>`:'<span>Personnel</span>'}<span class="${overdue?'task-late':''}">${esc(date)}${t.time?' · '+esc(t.time):''}</span>${t.minutes?`<span>${Number(t.minutes)} min</span>`:''}</div></div><span class="task-priority-chip ${['high','medium','low'].includes(t.priority)?t.priority:'medium'}">${taskPriorityNames[t.priority]||'Normale'}</span><details class="action-menu"><summary aria-label="Actions pour ${esc(t.title)}">•••</summary><div><button type="button" data-task-edit="${esc(t.id)}">Modifier</button>${!t.done?`<button type="button" data-task-focus="${esc(t.id)}">Préparer une session</button>`:''}<button type="button" data-task-duplicate="${esc(t.id)}">Dupliquer</button><button type="button" data-task-tomorrow="${esc(t.id)}">Reporter à demain</button><button type="button" class="danger-action" data-task-remove="${esc(t.id)}">Supprimer</button></div></details></article>`;
}
function renderTaskWorkspaceResults(){
 const target=document.querySelector('#taskWorkspaceResults');if(!target)return;
 const priorities={high:0,medium:1,low:2};
 const tasks=state.tasks.filter(t=>taskMatchesView(t)&&(!taskQuery||`${t.title} ${t.subject||''}`.toLocaleLowerCase('fr').includes(taskQuery.toLocaleLowerCase('fr')))&&(!taskSubjectFilter||t.subject===taskSubjectFilter)&&(!taskPriorityFilter||(t.priority||'medium')===taskPriorityFilter)).sort((a,b)=>taskSortOrder==='priority'?(priorities[a.priority]??1)-(priorities[b.priority]??1)||String(a.date).localeCompare(String(b.date)):taskSortOrder==='duration'?(Number(a.minutes)||0)-(Number(b.minutes)||0):String(a.date||'9999').localeCompare(String(b.date||'9999'))||String(a.time||'').localeCompare(String(b.time||'')));
 document.querySelector('#taskResultCount').textContent=`${tasks.length} tâche${tasks.length!==1?'s':''}`;
 if(!tasks.length){target.innerHTML=`<div class="task-work-empty">${uiIcon('tasks')}<h2>${state.tasks.length?'Aucune tâche dans cette vue':'Une journée bien organisée commence ici.'}</h2><p>${state.tasks.length?'Essaie un autre filtre ou ajoute une nouvelle tâche.':'Ajoute ton premier cours à revoir, exercice ou objectif.'}</p><button class="secondary-btn" ${state.tasks.length?'data-task-clear':'data-task-new'}>${state.tasks.length?'Réinitialiser les filtres':'+ Nouvelle tâche'}</button></div>`;return}
 const today=todayISO(),groups=[['overdue','En retard',t=>!t.done&&t.date&&t.date<today],['today','Aujourd’hui',t=>!t.done&&t.date===today],['future','À venir',t=>!t.done&&t.date>today],['undated','Sans date',t=>!t.done&&!t.date],['done','Terminées',t=>t.done]];
 target.innerHTML=groups.map(([key,label,match])=>{const rows=tasks.filter(match);return rows.length?`<section class="task-work-group"><h2 class="${key==='overdue'?'task-late':''}">${label}<span>${rows.length}</span></h2>${rows.map(taskWorkspaceRow).join('')}</section>`:''}).join('');
}
renderTasks=function(){
 const today=todayISO(),due=state.tasks.filter(t=>t.date===today),completed=due.filter(t=>t.done).length,late=state.tasks.filter(t=>!t.done&&t.date&&t.date<today).length,minutes=due.filter(t=>!t.done).reduce((n,t)=>n+Number(t.minutes||0),0),pct=due.length?Math.round(completed/due.length*100):0;
 const subjects=[...new Set([...state.subjects.map(s=>s.name),...state.tasks.map(t=>t.subject).filter(Boolean)])];
 const next=state.tasks.filter(t=>!t.done).sort((a,b)=>String(a.date||'9999').localeCompare(String(b.date||'9999'))||({high:0,medium:1,low:2}[a.priority]??1)-({high:0,medium:1,low:2}[b.priority]??1)).slice(0,3);
 document.querySelector('#page').innerHTML=`<div class="tasks-workspace"><header class="work-heading"><div><span class="work-kicker">TON ORGANISATION</span><h1>Mes tâches</h1><p>Fais de la place pour ce qui compte aujourd’hui.</p></div><button class="primary-btn" data-task-new>+ Nouvelle tâche</button></header><div class="task-work-layout"><section class="task-work-main"><div class="task-work-tabs" role="group" aria-label="Vue des tâches">${[['all','Toutes'],['today','Aujourd’hui'],['upcoming','À venir'],['overdue','En retard'],['done','Terminées']].map(([id,label])=>`<button type="button" data-task-view="${id}" class="${taskView===id?'active':''}" aria-pressed="${taskView===id}">${label}<span>${state.tasks.filter(t=>taskMatchesView(t,id)).length}</span></button>`).join('')}</div><div class="task-work-card"><form id="taskQuickAdd" class="task-quick-add"><span aria-hidden="true">+</span><input name="title" aria-label="Ajouter une tâche pour aujourd’hui" placeholder="Nouvelle tâche…" maxlength="180" required><button type="submit">Ajouter</button></form><div class="task-work-filters"><label class="task-search">${uiIcon('search')}<input type="search" id="taskQuery" aria-label="Rechercher une tâche" placeholder="Rechercher une tâche" value="${esc(taskQuery)}"></label><select id="taskSubjectFilter" aria-label="Filtrer par matière"><option value="">Toutes les matières</option>${subjects.map(name=>`<option value="${esc(name)}" ${taskSubjectFilter===name?'selected':''}>${esc(name)}</option>`).join('')}</select><select id="taskPriorityFilter" aria-label="Filtrer par priorité"><option value="">Toutes les priorités</option>${Object.entries(taskPriorityNames).map(([id,label])=>`<option value="${id}" ${taskPriorityFilter===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="task-results-heading"><span id="taskResultCount" aria-live="polite"></span><label>Trier : <select id="taskSortOrder" aria-label="Trier les tâches"><option value="date" ${taskSortOrder==='date'?'selected':''}>Échéance</option><option value="priority" ${taskSortOrder==='priority'?'selected':''}>Priorité</option><option value="duration" ${taskSortOrder==='duration'?'selected':''}>Durée</option></select></label></div><div id="taskWorkspaceResults"></div></div></section><aside class="task-day-plan"><div class="task-day-title"><span>AUJOURD’HUI</span>${uiIcon('calendar')}</div><h2>Ton programme</h2><div class="task-day-progress"><strong>${completed}<small> / ${due.length}</small></strong><span>tâches terminées</span></div><div class="task-day-track"><span style="width:${pct}%"></span></div><div class="task-day-facts"><div><strong>${minutes>=60?`${Math.floor(minutes/60)} h ${minutes%60?String(minutes%60).padStart(2,'0'):''}`:minutes+' min'}</strong><span>de travail prévu restant</span></div><button data-task-view="overdue"><strong>${late}</strong><span>en retard</span></button></div><h3>À traiter ensuite</h3>${next.map(t=>`<button class="task-next" data-task-edit="${esc(t.id)}"><span class="task-next-dot ${t.priority==='high'?'high':''}"></span><span><strong>${esc(t.title)}</strong><small>${t.date===today?'Aujourd’hui':t.date?formatShort(t.date):'Sans date'}${t.minutes?' · '+Number(t.minutes)+' min':''}</small></span>${uiIcon('right')}</button>`).join('')||'<p class="task-plan-empty">Tout est à jour. Ton prochain objectif apparaîtra ici.</p>'}<button class="secondary-btn task-to-calendar" data-go="calendar">Ouvrir le calendrier ${uiIcon('right')}</button></aside></div></div>`;
 renderTaskWorkspaceResults();
 document.querySelector('#taskQuickAdd').onsubmit=e=>{e.preventDefault();const title=e.target.elements.title.value.trim();if(!title)return;state.tasks.push({id:uid('t'),title,date:todayISO(),time:'',subject:taskSubjectFilter,priority:taskPriorityFilter||'medium',minutes:0,done:false});taskView='today';taskQuery='';save();render();document.querySelector('#taskQuickAdd input').focus();showToast('Tâche ajoutée pour aujourd’hui')};
};
const focusBeforeRefinement=renderFocus;
let focusImmersive=false,focusAudioContext;
function focusChime(){
 if(!focusAudioContext)return;
 try{focusAudioContext.resume();const volume=Math.min(.4,Math.max(0,Number(state.focusSettings.soundVolume??40)/250));[660,880].forEach((hz,i)=>{const oscillator=focusAudioContext.createOscillator(),gain=focusAudioContext.createGain(),at=focusAudioContext.currentTime+i*.22;oscillator.frequency.value=hz;gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(volume,at+.015);gain.gain.exponentialRampToValueAtTime(.001,at+.55);oscillator.connect(gain);gain.connect(focusAudioContext.destination);oscillator.start(at);oscillator.stop(at+.6)})}catch{}
}
function unlockFocusSound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){focusAudioContext||=new Audio();focusAudioContext.resume()}}catch{}}
const finishBeforeRefinement=finishFocus;
finishFocus=function(){const naturallyFinished=focusRun.left<=0;if(naturallyFinished&&state.focusSettings.endSound)focusChime();return finishBeforeRefinement()};
renderFocus=function(){
 focusBeforeRefinement();const settings=state.focusSettings,locked=focusRun.running||focusRun.left<focusRun.duration;
 const page=document.querySelector('#page'),layout=page.querySelector('.polished-focus');layout.classList.add('focus-personal');layout.classList.toggle('focus-immersive',focusImmersive);layout.dataset.timerTheme=settings.timerTheme==='dark'?'dark':'light';
 const rhythms=[{name:'Pomodoro',work:25,break:5},{name:'Travail profond',work:50,break:10},{name:'Longue session',work:90,break:15},...(settings.savedRhythms||[])];
 page.querySelector('.focus-presets').outerHTML=`<button type="button" class="focus-immersive-button" data-focus-immersive aria-pressed="${focusImmersive}">${focusImmersive?'Quitter le mode immersif':'Mode immersif'}</button>`;
 page.querySelector('.focus-main').insertAdjacentHTML('afterbegin',`<div class="focus-rhythms" role="group" aria-label="Rythmes de concentration">${rhythms.map((r,i)=>`<div><button type="button" data-focus-rhythm="${i}" class="${settings.work===r.work&&settings.break===r.break?'active':''}" ${locked?'disabled':''}><strong>${esc(r.name)}</strong><span>${Number(r.work)} min · ${Number(r.break)} min de pause</span></button>${i>=3?`<button type="button" class="rhythm-remove" data-rhythm-remove="${i-3}" aria-label="Supprimer le rythme ${esc(r.name)}" ${locked?'disabled':''}>×</button>`:''}</div>`).join('')}</div>`);
 page.querySelector('.timer-surface').insertAdjacentHTML('afterbegin',`<div class="focus-session-context"><span>${esc(focusRun.subject||settings.subject||'Étude libre')}</span><p>${esc(focusRun.objective||settings.objective||'Un objectif à la fois.')}</p></div>`);
 page.querySelector('.focus-settings h2').textContent='Personnaliser ma session';
 const form=page.querySelector('#focusSettings');
 form.querySelector('button[type="submit"]').insertAdjacentHTML('beforebegin',`<div class="focus-custom-options"><label for="timerTheme">Apparence du chrono</label><select id="timerTheme" name="timerTheme"><option value="light" ${settings.timerTheme!=='dark'?'selected':''}>Clair</option><option value="dark" ${settings.timerTheme==='dark'?'selected':''}>Bleu nuit</option></select><label class="focus-sound-toggle"><input type="checkbox" name="endSound" ${settings.endSound?'checked':''}> Son en fin de session</label><div class="focus-volume"><label for="soundVolume">Volume</label><input id="soundVolume" name="soundVolume" type="range" min="0" max="100" value="${Number(settings.soundVolume??40)}"><button type="button" data-focus-sound-test aria-label="Tester le son">Tester</button></div></div>`);
 form.insertAdjacentHTML('beforeend',`<div class="focus-save-rhythm"><label for="rhythmName">Garder ce rythme</label><div><input id="rhythmName" maxlength="30" placeholder="Ex. Révisions du soir" ${locked?'disabled':''}><button type="button" data-rhythm-save ${locked?'disabled':''}>Enregistrer</button></div><small>Enregistre les durées d’étude et de pause.</small></div><p class="helper">${locked?'Durées et matière verrouillées pendant la session.':'Le temps étudié est ajouté à ta progression.'}</p>`);
 form.onsubmit=e=>{e.preventDefault();const data=new FormData(form);settings.goal=Number(data.get('goal'));settings.timerTheme=data.get('timerTheme');settings.endSound=data.get('endSound')==='on';settings.soundVolume=Number(data.get('soundVolume'));if(settings.endSound)unlockFocusSound();if(!locked){settings.work=Number(data.get('work'));settings.break=Number(data.get('break'));settings.subject=data.get('subject');focusRun.subject=settings.subject;focusRun.duration=focusRun.left=settings[focusRun.mode]*60}persistFocus();render();showToast('Réglages enregistrés')};
 if(focusImmersive)page.querySelector('.session-history').hidden=true;
};
document.addEventListener('input',e=>{if(e.target.id==='taskQuery'){taskQuery=e.target.value;renderTaskWorkspaceResults()}});
document.addEventListener('change',e=>{if(e.target.id==='taskSubjectFilter')taskSubjectFilter=e.target.value;else if(e.target.id==='taskPriorityFilter')taskPriorityFilter=e.target.value;else if(e.target.id==='taskSortOrder')taskSortOrder=e.target.value;else return;renderTaskWorkspaceResults()});
document.addEventListener('click',e=>{
 if(e.target.closest('[data-task-clear]')){taskQuery=taskSubjectFilter=taskPriorityFilter='';taskView='all';render()}
 const tomorrow=e.target.closest('[data-task-tomorrow]');if(tomorrow){const task=state.tasks.find(t=>t.id===tomorrow.dataset.taskTomorrow);if(task){const date=new Date();date.setDate(date.getDate()+1);task.date=localISO(date);save();render();showToast('Tâche reportée à demain')}}
 if(e.target.closest('[data-focus-immersive]')){focusImmersive=!focusImmersive;render()}
 if(e.target.closest('[data-focus-action="toggle"]')&&state.focusSettings.endSound)unlockFocusSound();
 if(e.target.closest('[data-focus-sound-test]')){unlockFocusSound();const volume=state.focusSettings.soundVolume;state.focusSettings.soundVolume=Number(document.querySelector('#soundVolume').value);focusChime();state.focusSettings.soundVolume=volume}
 const rhythm=e.target.closest('[data-focus-rhythm]');if(rhythm&&!rhythm.disabled){const all=[{work:25,break:5},{work:50,break:10},{work:90,break:15},...(state.focusSettings.savedRhythms||[])],r=all[Number(rhythm.dataset.focusRhythm)];if(r){Object.assign(state.focusSettings,{work:r.work,break:r.break});focusRun.duration=focusRun.left=r[focusRun.mode]*60;persistFocus();render()}}
 const remove=e.target.closest('[data-rhythm-remove]');if(remove&&!remove.disabled){state.focusSettings.savedRhythms.splice(Number(remove.dataset.rhythmRemove),1);persistFocus();render()}
 const add=e.target.closest('[data-rhythm-save]');if(add&&!add.disabled){const form=document.querySelector('#focusSettings'),name=document.querySelector('#rhythmName').value.trim();if(!name){document.querySelector('#rhythmName').focus();showToast('Donne un nom à ton rythme');return}if(!form.reportValidity())return;const rows=state.focusSettings.savedRhythms||[];if(rows.length>=6){showToast('Tu peux garder jusqu’à 6 rythmes. Supprime un ancien rythme.');return}rows.push({name,work:Number(form.elements.work.value),break:Number(form.elements.break.value)});state.focusSettings.savedRhythms=rows;persistFocus();render();showToast('Rythme enregistré')}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focusImmersive){focusImmersive=false;if(currentPage==='focus')render()}});
